72	/* CP owns these shared SYS controls while CPU1 is held in reset.  Keep the
73	 * three whole-word RMW operations in that exclusive window, then verify the
74	 * hardware-visible values before AP can execute any audio initialization.
75	 */
76	
77	static int bk7258_ap_audio_wake(
78	  struct bk7258_ap_audio_wake_s *state)
79	{
80	  state->power_before =
81	    bk7258_ap_reg_read(BK7258_SYS_POWER_WAKEUP);
82	  state->mem_ctrl1_before =
83	    bk7258_ap_reg_read(BK7258_SYS_DEV_MEM_CTRL1);
84	  state->mem_ctrl2_before =
85	    bk7258_ap_reg_read(BK7258_SYS_DEV_MEM_CTRL2);
86	
87	  bk7258_ap_reg_write(BK7258_SYS_POWER_WAKEUP,
88	                      state->power_before &
89	                      ~BK7258_SYS_AUDP_POWER_DOWN);
90	  bk7258_ap_reg_write(BK7258_SYS_DEV_MEM_CTRL1,
91	                      state->mem_ctrl1_before &
92	                      ~BK7258_SYS_AUD_MEM_LOW_POWER);
93	  bk7258_ap_reg_write(BK7258_SYS_DEV_MEM_CTRL2,
94	                      state->mem_ctrl2_before &
95	                      ~BK7258_SYS_AUD_MEM_LOW_POWER);
96	  bk7258_ap_lifecycle_barrier();
97	  up_udelay(10);
98	
99	  state->power_after =
100	    bk7258_ap_reg_read(BK7258_SYS_POWER_WAKEUP);
101	  state->mem_ctrl1_after =
102	    bk7258_ap_reg_read(BK7258_SYS_DEV_MEM_CTRL1);
103	  state->mem_ctrl2_after =
104	    bk7258_ap_reg_read(BK7258_SYS_DEV_MEM_CTRL2);
105	
106	  if ((state->power_after & BK7258_SYS_AUDP_POWER_DOWN) != 0 ||
107	      (state->mem_ctrl1_after & BK7258_SYS_AUD_MEM_LOW_POWER) != 0 ||
108	      (state->mem_ctrl2_after & BK7258_SYS_AUD_MEM_LOW_POWER) != 0)
109	    {
110	      return -EIO;
111	    }
112	
113	  return 0;
114	}
