263	    }
264	
265	  flags = up_irq_save();
266	
267	  /* Follow Armino's BK7258 lifecycle order. CPU_CURRENT_RUN_STATUS is
268	   * diagnostic only; its transient values are not a launch precondition. */
269	
270	  control = bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL);
271	  syslog(LOG_INFO, "[AP] start: cpu1_ctrl before=%08lx\n",
272	         (unsigned long)control);
273	  control &= ~(BK7258_SYS_CPU1_RESET_RELEASE |
274	               BK7258_SYS_CPU1_POWER_DOWN |
275	               BK7258_SYS_CPU1_HALT |
276	               BK7258_SYS_CPU1_OFFSET_MASK);
277	  control |= BK7258_SYS_CPU1_RXEVT_SEL;
278	  bk7258_ap_reg_write(BK7258_SYS_CPU1_CTRL, control);
279	  bk7258_ap_lifecycle_barrier();
280	  expected = control & BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK;
281	  if ((bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL) &
282	       BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK) != expected)
283	    {
284	      syslog(LOG_ERR,
285	             "[AP] start: cpu1_ctrl readback=%08lx expected=%08lx -> EIO\n",
286	             (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL),
287	             (unsigned long)expected);
288	      up_irq_restore(flags);
289	      ret = -EIO;
290	      goto out_unlock;
291	    }
292	
293	  /* Keep the vendor power-domain settling window explicit and
294	   * non-optimizable. */
295	
296	  for (count = 0; count < BK7258_AP_POWER_STABILIZE_LOOPS; count++)
297	    {
298	      __asm__ volatile ("nop");
299	    }
300	
301	  for (count = 0; count < BK7258_AP_POWER_WAIT_LOOPS; count++)
302	    {
303	      status = bk7258_ap_reg_read(BK7258_SYS_CPU_STATUS);
304	      if ((status & (BK7258_SYS_CPU1_PWR_DW_STATE |
305	                     BK7258_SYS_CPU1_HALTED_STATE |
306	                     BK7258_SYS_CPU1_RESET_STATE)) == 0)
307	        {
308	          break;
309	        }
310	    }
311	
312	  if (count == BK7258_AP_POWER_WAIT_LOOPS)
313	    {
314	      syslog(LOG_ERR,
315	             "[AP] start: power-wait timeout cpu_status=%08lx -> ETIMEDOUT\n",
316	             (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU_STATUS));
317	      up_irq_restore(flags);
318	      ret = -ETIMEDOUT;
319	      goto out_unlock;
320	    }
321	
322	  syslog(LOG_INFO, "[AP] start: cpu1 powered up, cpu_status=%08lx after %u\n",
323	         (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU_STATUS),
324	         (unsigned int)count);
325	
326	  /* CPU1 is still held in reset and CP interrupts remain disabled, so this
327	   * is the exclusive ownership window for the shared audio power/SRAM RMWs.
328	   * A failed readback keeps AP in reset and prevents an unusable audio
329	   * subsystem from being published.
330	   */
331	
332	  audio_wake_attempted = true;
333	  audio_wake_ret = bk7258_ap_audio_wake(&audio_wake);
334	  if (audio_wake_ret < 0)
335	    {
336	      up_irq_restore(flags);
337	      ret = audio_wake_ret;
338	      goto out_unlock;
339	    }
340	
341	  /* CPU1 is now held in reset, so CP owns SWAP exclusively while it creates
342	   * the next boot sequence. This ordering also makes a future AP restart safe:
343	   * the old AP cannot race the new CP record with a final heartbeat write. */
344	
345	  boot_sequence = bk7258_ap_record_prepare();
346	
347	  control = bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL);
348	  control &= ~(BK7258_SYS_CPU1_OFFSET_MASK |
349	               BK7258_SYS_CPU1_RESET_RELEASE);
350	  /* The Armino setter takes address >> 8 as a bitfield value. This direct
351	   * register write must place that value back into bits [31:8]. */
352	
353	  control |= BK7258_SYS_CPU_BOOT_OFFSET(BK7258_AP_XIP_VECTOR_BASE);
354	  control |= BK7258_SYS_CPU1_RXEVT_SEL;
355	  bk7258_ap_reg_write(BK7258_SYS_CPU1_CTRL, control);
356	  bk7258_ap_lifecycle_barrier();
357	  expected = control & BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK;
358	  if ((bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL) &
359	       BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK) != expected)
360	    {
361	      syslog(LOG_ERR,
362	             "[AP] start: vec-offset readback=%08lx expected=%08lx -> EIO\n",
363	             (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL),
364	             (unsigned long)expected);
365	      up_irq_restore(flags);
366	      ret = -EIO;
367	      goto out_unlock;
368	    }
369	
370	  syslog(LOG_INFO, "[AP] start: releasing CPU1 reset (seq=%u)\n",
371	         (unsigned int)boot_sequence);
372	  bk7258_ap_reg_write(BK7258_SYS_CPU1_CTRL,
373	                      control | BK7258_SYS_CPU1_RESET_RELEASE);
374	  released = true;
375	  bk7258_ap_lifecycle_barrier();
376	  expected = (control | BK7258_SYS_CPU1_RESET_RELEASE) &
377	             BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK;
378	  if ((bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL) &
379	       BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK) != expected)
380	    {
381	      syslog(LOG_ERR,
382	             "[AP] start: release readback=%08lx expected=%08lx -> EIO\n",
383	             (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL),
384	             (unsigned long)expected);
385	      up_irq_restore(flags);
386	      ret = -EIO;
387	      goto out_rollback;
388	    }
389	
390	  for (count = 0; count < BK7258_AP_POWER_WAIT_LOOPS; count++)
391	    {
392	      status = bk7258_ap_reg_read(BK7258_SYS_CPU_STATUS);
393	      if ((status & BK7258_SYS_CPU1_RESET_STATE) != 0)
394	        {
395	          break;
396	        }
397	    }
398	
399	  if (count == BK7258_AP_POWER_WAIT_LOOPS)
400	    {
401	      syslog(LOG_ERR,
402	             "[AP] start: post-release reset-state timeout "
403	             "cpu_status=%08lx -> ETIMEDOUT\n",
404	             (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU_STATUS));
405	      up_irq_restore(flags);
406	      ret = -ETIMEDOUT;
407	      goto out_rollback;
408	    }
409	
410	  up_irq_restore(flags);
411	
412	  /* Do not report a successful start merely because MMIO writes completed.
413	   * The current-sequence RESET_ENTERED record proves CPU1 fetched the AP
414	   * vector and executed team OpenVela startup code. */
415	
416	  for (count = 0; count < BK7258_AP_RESET_WAIT_ATTEMPTS; count++)
417	    {
418	      if (bk7258_ap_record_read(&record) &&
419	          record.boot_sequence == boot_sequence)
420	        {
421	          if (record.stage == BK7258_AP_STAGE_RESET_ENTERED ||
422	              record.stage == BK7258_AP_STAGE_SCHEDULER_RUNNING)
423	            {
424	              g_ap_boot_sequence = boot_sequence;
425	              g_ap_started = true;
426	              syslog(LOG_INFO,
427	                     "[AP] start: OK stage=%s seq=%u after %u\n",
428	                     bk7258_ap_stage_name(record.stage),
429	                     (unsigned int)boot_sequence,
430	                     (unsigned int)count);
431	              ret = 0;
432	              goto out_unlock;
433	            }
434	
435	          if (record.stage == BK7258_AP_STAGE_FAULT)
436	            {
437	              syslog(LOG_ERR,
438	                     "[AP] start fault seq=%u code=0x%08x\n",
439	                     (unsigned int)boot_sequence,
440	                     (unsigned int)record.fault);
441	              ret = -EFAULT;
442	              goto out_rollback;
443	            }
444	        }
445	
446	      nxsig_usleep(BK7258_AP_RESET_WAIT_USEC);
447	    }
448	
449	  syslog(LOG_ERR,
450	         "[AP] start: boot-record wait timeout seq=%u attempts=%u "
451	         "(last valid=%d seq=%u stage=%u) -> ETIMEDOUT\n",
452	         (unsigned int)boot_sequence,
453	         (unsigned int)BK7258_AP_RESET_WAIT_ATTEMPTS,
454	         (int)bk7258_ap_record_read(&record),
455	         (unsigned int)record.boot_sequence,
456	         (unsigned int)record.stage);
457	  ret = -ETIMEDOUT;
458	
459	out_rollback:
460	  if (released)
461	    {
462	      int reset_ret = bk7258_ap_force_reset();
463	      if (reset_ret < 0)
464	        {
465	          syslog(LOG_ERR, "[AP] rollback reset failed: %d\n", reset_ret);
466	        }
467	    }
468	
469	out_unlock:
470	  if (audio_wake_attempted)
471	    {
472	      syslog(audio_wake_ret < 0 ? LOG_ERR : LOG_INFO,
473	             "[AP] audio wake ret=%d pwr=%08lx->%08lx "
474	             "sd=%08lx->%08lx ds=%08lx->%08lx\n",
475	             audio_wake_ret,
476	             (unsigned long)audio_wake.power_before,
477	             (unsigned long)audio_wake.power_after,
478	             (unsigned long)audio_wake.mem_ctrl1_before,
479	             (unsigned long)audio_wake.mem_ctrl1_after,
480	             (unsigned long)audio_wake.mem_ctrl2_before,
481	             (unsigned long)audio_wake.mem_ctrl2_after);
482	    }
483	
484	  nxmutex_unlock(&g_ap_start_lock);
485	  return ret;
486	}
487	
488	static int bk7258_ap_recover_transport(void)
489	{
490	  unsigned int attempt;
491	  int ret;
492	
493	  if (g_ap_recovering)
494	    {
495	      return -EALREADY;
496	    }
497	
498	  g_ap_recovering = true;
499	  g_ap_started = false;
500	
501	  /* The generic RPTUN stop path destroys the remoteproc VirtIO device and
502	   * broadcasts RPMsg device-destroy callbacks before returning the transport
503	   * to OFFLINE.  Do this before board_start_cpu() resets AP again, otherwise
504	   * the old vrings and uart_rpmsg endpoint can survive into the new AP
505	   * generation. */
506	
507	  /* remoteproc_stop() rejects CONFIGURED/READY while the RPTUN worker is
508	   * still completing its start transaction.  AP can reboot exactly during
509	   * that window, so treat -EBUSY as a transient state and retry in this
510	   * task context.  Do not call rptun_initialize() here: the /dev/rptun/ap
511	   * instance is already registered and initialization is one-shot. */
512	
513	  ret = -EBUSY;
514	  for (attempt = 0; attempt < BK7258_AP_RPTUN_STOP_ATTEMPTS; attempt++)
515	    {
516	      ret = rptun_poweroff("ap");
517	      if (ret != -EBUSY)
518	        {
519	          break;
520	        }
521	
522	      nxsig_usleep(BK7258_AP_RPTUN_STOP_WAIT_USEC);
523	    }
524	
525	  if (ret == -EBUSY)
526	    {
527	      syslog(LOG_ERR,
528	             "[AP] RPTUN teardown remained busy after %u attempts\n",
529	             BK7258_AP_RPTUN_STOP_ATTEMPTS);
530	    }
531	
532	  if (ret < 0 && ret != -ENODEV)
533	    {
534	      syslog(LOG_ERR, "[AP] RPTUN teardown failed: %d\n", ret);
535	      goto out;
536	    }
537	
538	  ret = rptun_boot("ap");
539	  if (ret < 0)
540	    {
541	      syslog(LOG_ERR, "[AP] RPTUN restart failed: %d\n", ret);
542	    }
543	
544	out:
545	  g_ap_recovering = false;
546	  return ret;
547	}
548	
549	static int bk7258_ap_monitor(int argc, char *argv[])
550	{
551	  struct bk7258_ap_boot_record_s record;
552	  uint32_t last_heartbeat = 0;
553	  uint32_t last_stage = UINT32_MAX;
554	  uint32_t last_dbg = 0;
555	  unsigned int invalid_samples = 0;
556	  unsigned int stagnant_samples = 0;
557	  bool invalid_reported = false;
558	  bool stalled_reported = false;
559	  bool heartbeat_seen = false;
560	
561	  (void)argc;
562	  (void)argv;
563	
564	  for (; ; )
565	    {
566	      if (!bk7258_ap_record_read(&record) ||
567	          (record.boot_sequence != g_ap_boot_sequence &&
568	           !g_ap_recovering))
569	        {
570	          if (bk7258_ap_record_read(&record) &&
571	              record.boot_sequence != g_ap_boot_sequence &&
572	              record.stage == BK7258_AP_STAGE_SCHEDULER_RUNNING)
573	            {
574	              syslog(LOG_INFO,
575	                     "[AP] peer generation changed old=%u new=%u; rebuilding RPTUN\n",
576	                     (unsigned int)g_ap_boot_sequence,
577	                     (unsigned int)record.boot_sequence);
578	              (void)bk7258_ap_recover_transport();
579	              nxsig_usleep(1000 * 1000);
580	              continue;
581	            }
582	
583	          invalid_samples++;
584	          stagnant_samples = 0;
585	          if (invalid_samples >= BK7258_AP_STALL_SAMPLES && !invalid_reported)
586	            {
587	              syslog(LOG_ERR,
588	                     "[AP] no valid record for seq=%u\n",
589	                     (unsigned int)g_ap_boot_sequence);
590	              invalid_reported = true;
591	            }
592	
593	          nxsig_usleep(1000 * 1000);
594	          continue;
595	        }
596	
597	      invalid_samples = 0;
598	      invalid_reported = false;
599	
600	      {
601	        uint32_t dbg = bk7258_ap_dbg_read();
602	
603	        if (dbg != last_dbg)
604	          {
605	            syslog(LOG_INFO, "[AP] bootmark=0x%08x\n", dbg);
606	            last_dbg = dbg;
607	          }
608	      }
609	
610	      if (record.stage != last_stage)
611	        {
612	          if (record.stage == BK7258_AP_STAGE_FAULT &&
613	              (record.fault & UINT32_C(0xffff0000)) ==
614	              (BK7258_AP_FAULT_PANIC_BASE & UINT32_C(0xffff0000)))
615	            {
616	              /* The AP panic notifier encodes the assertion location:
617	               * high byte = a short hash of the filename, low byte = line
618	               * number. */
619	
620	              syslog(LOG_ERR,
621	                     "[AP] stage=fault seq=%u panic filehash=0x%02x line=%u\n",
622	                     (unsigned int)record.boot_sequence,
623	                     (unsigned int)((record.fault >> 8) & UINT32_C(0xff)),
624	                     (unsigned int)(record.fault & UINT32_C(0xff)));
625	            }
626	          else
627	            {
628	              syslog(record.stage == BK7258_AP_STAGE_FAULT ? LOG_ERR : LOG_INFO,
629	                     "[AP] stage=%s seq=%u fault=0x%08x\n",
630	                     bk7258_ap_stage_name(record.stage),
631	                     (unsigned int)record.boot_sequence,
632	                     (unsigned int)record.fault);
633	            }
634	
635	          last_stage = record.stage;
636	        }
637	
638	      if (record.stage == BK7258_AP_STAGE_SCHEDULER_RUNNING)
639	        {
640	          if (record.heartbeat != last_heartbeat)
641	            {
642	              stagnant_samples = 0;
643	              stalled_reported = false;
644	              last_heartbeat = record.heartbeat;
645	              heartbeat_seen = true;
646	            }
647	          else if (heartbeat_seen)
648	            {
649	              stagnant_samples++;
650	              if (stagnant_samples >= BK7258_AP_STALL_SAMPLES &&
651	                  !stalled_reported)
652	                {
653	                  syslog(LOG_ERR,
654	                         "[AP] stalled seq=%u heartbeat=%u samples=%u\n",
655	                         (unsigned int)record.boot_sequence,
656	                         (unsigned int)record.heartbeat,
657	                         stagnant_samples);
658	                  stalled_reported = true;
659	                }
660	            }
661	        }
662	
663	      nxsig_usleep(1000 * 1000);
664	    }
665	
666	  return 0;
667	}
668	
669	int bk7258_ap_start_monitor(void)
670	{
671	  int ret;
672	
673	  ret = boardctl(BOARDIOC_START_CPU, 1);
674	  if (ret < 0)
675	    {
676	      syslog(LOG_ERR, "[AP] CPU1 release failed: %d errno=%d\n",
677	             ret, get_errno());
678	      return ret;
679	    }
680	
681	  syslog(LOG_INFO, "[AP] release seq=%u vector=0x%08x\n",
682	         (unsigned int)g_ap_boot_sequence,
683	         (unsigned int)BK7258_AP_XIP_VECTOR_BASE);
684	
685	  /* RPTUN restart reuses the long-lived CP monitor. Do not create a second
686	   * monitor thread when the generic RPTUN start path rebuilds a transport. */
687	
688	  if (g_ap_monitor_started)
689	    {
690	      return 0;
691	    }
692	
693	  ret = kthread_create("ap-monitor", BK7258_AP_MONITOR_PRIORITY,
694	                       BK7258_AP_MONITOR_STACK_SIZE,
695	                       bk7258_ap_monitor, NULL);
696	  if (ret < 0)
697	    {
698	      syslog(LOG_ERR, "[AP] monitor creation failed: %d\n", ret);
699	      nxmutex_lock(&g_ap_start_lock);
700	      (void)bk7258_ap_force_reset();
701	      g_ap_started = false;
702	      nxmutex_unlock(&g_ap_start_lock);
703	      return ret;
704	    }
705	
706	  return 0;
707	}
