93	/* Debug boot-progress markers written by the AP cores into SWAP word 40.
94	 * The CP monitor prints marker changes so a silent bring-up stall can be
95	 * attributed to a specific core/step.  Bring-up diagnostics only: removed
96	 * once the SMP start path is stable on hardware. */
97	
98	#define BK7258_AP_SWAP_DBG_WORD         UINT32_C(40)
99	
100	#define BK7258_AP_DBG_MARK_RESET_DONE       0x0101u
101	#define BK7258_AP_DBG_MARK_BEFORE_NX        0x0102u
102	#define BK7258_AP_DBG_MARK_BOARD_EARLY      0x0103u
103	#define BK7258_AP_DBG_MARK_C2START_ENTRY    0x0200u
104	#define BK7258_AP_DBG_MARK_C2START_CTRL1    0x0201u
105	#define BK7258_AP_DBG_MARK_C2START_RELEASED 0x0202u
106	#define BK7258_AP_DBG_MARK_C2START_HANDSHAKE_OK 0x0203u
107	#define BK7258_AP_DBG_MARK_CPU2_ENTRY       0x0300u
108	#define BK7258_AP_DBG_MARK_CPU2_DISCARDED   0x0301u
109	#define BK7258_AP_DBG_MARK_CPU2_IRQ_ARMED   0x0302u
110	#define BK7258_AP_DBG_MARK_CPU2_READY       0x0303u
