120	 * Name: bk7258_cpu2_boot
121	 *
122	 * Description:
123	 *   Secondary (physical CPU2) reset entry.  .bss/.data are already
124	 *   initialized by CPU1; this core only needs its own stacks, NVIC, VTOR
125	 *   and IPI doorbell before handing over to the NuttX idle trampoline.
126	 *
127	 ****************************************************************************/
128	
129	static void bk7258_cpu2_boot(void)
130	{
131	  __asm__ volatile ("cpsid i" : : : "memory");
132	
133	  bk7258_ap_dbg_mark(BK7258_AP_DBG_MARK_CPU2_ENTRY);
134	
135	  /* CPU2 may inherit cache state from the Bootloader/vendor AP lifecycle.
136	   * Match the CPU1 policy: deterministic uncached shared-SRAM path. */
137	
138	  if ((getreg32(NVIC_CFGCON) & NVIC_CFGCON_DC) != 0)
139	    {
140	      up_disable_dcache();
141	    }
142	
143	  up_enable_icache();
144	
145	  /* Set up the per-CPU interrupt stack and select PSP for thread mode.  This
146	   * uses this_cpu() == 1, resolved from the CPU2 boot-stack MSP. */
147	
148	#if CONFIG_ARCH_INTERRUPTSTACK > 7
149	  arm_initialize_stack();
150	#endif
151	
152	  /* Reuse the primary-core NVIC exception setup: the vector table and the
153	   * shared irq_attach() table are valid on every AP core, and the NVIC
154	   * itself is core-local so this does not disturb CPU1. */
155	
156	  up_irqinitialize();
157	
158	  /* up_irqinitialize() ends by enabling interrupts.  Do not let any pending
159	   * NVIC line (Mailbox doorbell, or a stale shared interrupt) fire on this
160	   * core before the scheduler owns it: re-mask everything and let the
161	   * scheduler re-enable interrupts in nx_idle_trampoline() -> sched_unlock().
162	   */
163	
164	  __asm__ volatile ("cpsid i" : : : "memory");
165	
166	  /* Release the boot handshake held by up_cpu_start(): the SWAP flag word is
167	   * what CPU1 polls instead of a cross-core spinlock, so bring-up does not
168	   * depend on exclusive-monitor semantics. */
169	
170	  bk7258_ap_c2flag_set();
171	
172	#ifdef CONFIG_SCHED_INSTRUMENTATION
173	  /* Notify that this CPU has started */
174	
175	  sched_note_cpu_started(this_task());
176	#endif
177	
178	#ifdef CONFIG_BK7258_MAILBOX
179	  /* Enable CPU2's Mailbox line only after the boot handshake is released.
180	   * The Mailbox IRQ is a shared line: enabling it too early lets the CP->AP
181	   * RPTUN doorbell (channel 1) keep interrupting this core before the idle
182	   * trampoline owns it, starving the boot path.  Discard this core's stale
183	   * FIFO entries first: a warm reset keeps Mailbox state alive, and an old
184	   * SMP_MAGIC entry dispatched here would run the SMP-call path before the
185	   * scheduler exists. */
186	
187	  bk7258_mbox_discard_local();
188	  bk7258_ap_dbg_mark(BK7258_AP_DBG_MARK_CPU2_DISCARDED);
189	  up_prioritize_irq(BK7258_IRQ_MAILBOX,
190	                    CONFIG_BK7258_MAILBOX_IRQ_PRIORITY);
191	  up_enable_irq(BK7258_IRQ_MAILBOX);
192	  bk7258_ap_dbg_mark(BK7258_AP_DBG_MARK_CPU2_IRQ_ARMED);
193	#endif
194	
195	  /* Then transfer control to the IDLE task */
196	
197	  bk7258_ap_dbg_mark(BK7258_AP_DBG_MARK_CPU2_READY);
198	  nx_idle_trampoline();
199	
200	  for (; ; )
201	    {
202	    }
203	}
