262	/****************************************************************************
263	 * Name: up_cpu_start
264	 ****************************************************************************/
265	
266	int up_cpu_start(int cpu)
267	{
268	  irqstate_t flags;
269	  uint32_t control;
270	  uint32_t expected;
271	  uint32_t status;
272	  unsigned int count;
273	  int ret = OK;
274	
275	  if (cpu != 1)
276	    {
277	      return -EINVAL;
278	    }
279	
280	#ifdef CONFIG_SCHED_INSTRUMENTATION
281	  /* Notify of the start event */
282	
283	  sched_note_cpu_start(this_task(), cpu);
284	#endif
285	
286	  /* Ensure the SMP doorbell and IPI handler are live before CPU2 exists. */
287	
288	  bk7258_smp_initialize();
289	  bk7258_ap_dbg_mark(BK7258_AP_DBG_MARK_C2START_ENTRY);
290	
291	  flags = up_irq_save();
292	
293	  /* Follow the CPU1 lifecycle order from bk7258_ap_control.c: power up and
294	   * unhalt CPU2 with reset asserted, program the boot vector, then release
295	   * reset.  The boot vector is the in-image _vectors_core1 table. */
296	
297	  control = getreg32(BK7258_SYS_CPU2_CTRL);
298	  control &= ~(BK7258_SYS_CPU2_RESET_RELEASE |
299	               BK7258_SYS_CPU2_POWER_DOWN |
300	               BK7258_SYS_CPU2_HALT |
301	               BK7258_SYS_CPU2_OFFSET_MASK);
302	  control |= BK7258_SYS_CPU2_RXEVT_SEL;
303	  putreg32(control, BK7258_SYS_CPU2_CTRL);
304	  __asm__ volatile ("dsb\n\tisb" : : : "memory");
305	  expected = control & BK7258_CPU2_CTRL_LIFECYCLE_MASK;
306	  if ((getreg32(BK7258_SYS_CPU2_CTRL) &
307	       BK7258_CPU2_CTRL_LIFECYCLE_MASK) != expected)
308	    {
309	      /* Visible instead of silent: the AP panic notifier is registered only
310	       * in board_late_initialize(), after nx_smp_start().  A failure here
311	       * would otherwise leave the CP monitor staring at reset-entered with
312	       * no fault record.  Low byte = the raw CTRL readback that mismatched.
313	       */
314	
315	      bk7258_ap_record_fault(BK7258_AP_FAULT_C2START_BASE |
316	                             (getreg32(BK7258_SYS_CPU2_CTRL) &
317	                              UINT32_C(0xff)));
318	      ret = -EIO;
319	      goto out;
320	    }
321	
322	  bk7258_ap_dbg_mark(BK7258_AP_DBG_MARK_C2START_CTRL1);
323	
324	  for (count = 0; count < BK7258_CPU2_POWER_STABILIZE_LOOPS; count++)
325	    {
326	      __asm__ volatile ("nop");
327	    }
328	
329	  control = getreg32(BK7258_SYS_CPU2_CTRL);
330	  control &= ~(BK7258_SYS_CPU2_OFFSET_MASK |
331	               BK7258_SYS_CPU2_RESET_RELEASE);
332	
333	  /* CPU2 uses the same 256-byte boot-offset field as CPU1. */
334	
335	  control |= BK7258_SYS_CPU_BOOT_OFFSET((uintptr_t)_vectors_core1);
336	  control |= BK7258_SYS_CPU2_RXEVT_SEL;
337	  putreg32(control, BK7258_SYS_CPU2_CTRL);
338	  __asm__ volatile ("dsb\n\tisb" : : : "memory");
339	  expected = control & BK7258_CPU2_CTRL_LIFECYCLE_MASK;
340	  if ((getreg32(BK7258_SYS_CPU2_CTRL) &
341	       BK7258_CPU2_CTRL_LIFECYCLE_MASK) != expected)
342	    {
343	      bk7258_ap_record_fault(BK7258_AP_FAULT_C2START_BASE |
344	                             (getreg32(BK7258_SYS_CPU2_CTRL) &
345	                              UINT32_C(0xff)));
346	      ret = -EIO;
347	      goto out;
348	    }
349	
350	  /* Clear the SWAP handshake flag while CPU2 is still held in reset, so a
351	   * stale value from an earlier CPU2 life can never satisfy the poll. */
352	
353	  bk7258_ap_c2flag_clear();
354	
355	  putreg32(control | BK7258_SYS_CPU2_RESET_RELEASE,
356	           BK7258_SYS_CPU2_CTRL);
357	  __asm__ volatile ("dsb\n\tisb" : : : "memory");
358	  bk7258_ap_dbg_mark(BK7258_AP_DBG_MARK_C2START_RELEASED);
359	
360	out:
361	  up_irq_restore(flags);
362	
363	  if (ret < 0)
364	    {
365	      return ret;
366	    }
367	
368	  /* Handshake on the dedicated SWAP flag word instead of a cross-core
369	   * spinlock: CPU1 cleared it before the release and CPU2 sets it once its
370	   * early boot completed.  Polling a plain SRAM word keeps bring-up
371	   * independent of the exclusive-monitor semantics that the runtime
372	   * scheduler spinlocks still need verified. */
373	
374	  for (count = 0; count < BK7258_CPU2_HANDSHAKE_LOOPS; count++)
375	    {
376	      if (bk7258_ap_c2flag_test())
377	        {
378	          break;
379	        }
380	    }
381	
382	  if (count == BK7258_CPU2_HANDSHAKE_LOOPS)
383	    {
384	      /* Fail loudly but stay diagnosable: the fault word carries the raw
385	       * CPU status and the CP monitor reports stage=fault, while nx_smp_start
386	       * turns -ETIMEDOUT into a recorded panic instead of a silent stall. */
387	
388	      status = getreg32(BK7258_SYS_CPU_STATUS);
389	      bk7258_ap_record_fault(BK7258_AP_FAULT_C2START_BASE |
390	                             (status & UINT32_C(0xff)));
391	      ret = -ETIMEDOUT;
392	    }
393	  else
394	    {
395	      bk7258_ap_dbg_mark(BK7258_AP_DBG_MARK_C2START_HANDSHAKE_OK);
396	    }
397	
398	  return ret;
399	}
