131	static int bk7258_capture_getcaps(FAR struct audio_lowerhalf_s *dev, int type,
132	                                  FAR struct audio_caps_s *caps)
133	{
134	  (void)dev;
135	  (void)type;
136	
137	  DEBUGASSERT(caps->ac_len >= sizeof(struct audio_caps_s));
138	
139	  caps->ac_format.hw   = 0;
140	  caps->ac_controls.w  = 0;
141	
142	  switch (caps->ac_type)
143	    {
144	      case AUDIO_TYPE_QUERY:
145	        caps->ac_channels = AUDIO_CHANNELS_RANGE(1, 1);
146	        switch (caps->ac_subtype)
147	          {
148	            case AUDIO_TYPE_QUERY:
149	              caps->ac_controls.b[0] = AUDIO_TYPE_INPUT;
150	              caps->ac_format.hw     = 1 << (AUDIO_FMT_PCM - 1);
151	              break;
152	
153	            case AUDIO_FMT_PCM:
154	              caps->ac_controls.b[0] = AUDIO_SUBFMT_PCM_S16_LE;
155	              break;
156	
157	            default:
158	              caps->ac_controls.b[0] = AUDIO_SUBFMT_END;
159	              break;
160	          }
161	        break;
162	
163	      case AUDIO_TYPE_INPUT:
164	        caps->ac_channels = AUDIO_CHANNELS_RANGE(1, 1);
165	        if (caps->ac_subtype == AUDIO_TYPE_QUERY)
166	          {
167	            /* 16 kHz mono — the rate the ASR path requires. */
168	            caps->ac_controls.hw[0] = AUDIO_SAMP_RATE_16K;
169	          }
170	        break;
171	
172	      default:
173	        caps->ac_subtype  = 0;
174	        caps->ac_channels = 0;
175	        break;
176	    }
177	
178	  return caps->ac_len;
179	}
