181	static int bk7258_capture_configure(FAR struct audio_lowerhalf_s *dev,
182	                                    FAR const struct audio_caps_s *caps)
183	{
184	  FAR struct bk7258_capture_s *priv =
185	      (FAR struct bk7258_capture_s *)dev;
186	  struct bk7258_adc_cfg_s adc_cfg;
187	  irqstate_t flags;
188	  uint32_t sample_rate;
189	  uint8_t  bpsamp;
190	  uint8_t  channels;
191	  int ret;
192	
193	  if (caps->ac_type != AUDIO_TYPE_INPUT)
194	    {
195	      return -EINVAL;
196	    }
197	
198	  sample_rate = caps->ac_controls.hw[0]
199	              | ((uint32_t)caps->ac_controls.b[3] << 16);
200	  channels = caps->ac_channels;
201	  bpsamp   = caps->ac_controls.b[2];
202	
203	  if (sample_rate == 0)
204	    {
205	      sample_rate = BK7258_AUDIO_DEFAULT_SAMPLE_RATE;
206	    }
207	
208	  if (channels == 0)
209	    {
210	      channels = 1;
211	    }
212	
213	  if (bpsamp == 0)
214	    {
215	      bpsamp = BK7258_AUDIO_DEFAULT_BPSAMP;
216	    }
217	
218	  if (bpsamp != 16)
219	    {
220	      CAP_ERR("only S16_LE supported (asked for %u)", bpsamp);
221	      return -EINVAL;
222	    }
223	
224	  if (channels != 1)
225	    {
226	      CAP_ERR("only mono supported (asked for %u)", channels);
227	      return -EINVAL;
228	    }
229	
230	  flags = spin_lock_irqsave(&priv->lock);
231	  if (priv->closing)
232	    {
233	      spin_unlock_irqrestore(&priv->lock, flags);
234	      return -ESHUTDOWN;
235	    }
236	
237	  priv->sample_rate = sample_rate;
238	  priv->channels    = channels;
239	  priv->bpsamp      = bpsamp;
240	  spin_unlock_irqrestore(&priv->lock, flags);
241	
242	  /* Program the ADC block.  Single analog MIC on the left input; the clock
243	   * mux is shared with the DAC and bk7258_adc_configure self-invokes
244	   * bk7258_aud_subsystem_init().
245	   */
246	
247	  adc_cfg.samp_rate = sample_rate;
248	  adc_cfg.channel   = BK7258_ADC_CHL_L;
249	  adc_cfg.gain      = BK7258_ADC_GAIN_DEFAULT;
250	  adc_cfg.samp_edge = false;
251	  adc_cfg.use_apll  = true;
252	
253	  ret = bk7258_adc_configure(&adc_cfg);
254	  if (ret < 0)
255	    {
256	      CAP_ERR("adc_configure failed: %d", ret);
257	      return ret;
258	    }
259	
260	  priv->configured = true;
261	  return OK;
262	}
263	
264	static int bk7258_capture_start(FAR struct audio_lowerhalf_s *dev)
265	{
266	  FAR struct bk7258_capture_s *priv = (FAR struct bk7258_capture_s *)dev;
267	  irqstate_t flags;
268	
269	  flags = spin_lock_irqsave(&priv->lock);
270	  if (priv->closing)
271	    {
272	      spin_unlock_irqrestore(&priv->lock, flags);
273	      return -ESHUTDOWN;
274	    }
275	
276	  if (!priv->configured)
277	    {
278	      spin_unlock_irqrestore(&priv->lock, flags);
279	      return -EINVAL;
280	    }
281	
282	  if (priv->running)
283	    {
284	      spin_unlock_irqrestore(&priv->lock, flags);
285	      return OK;
286	    }
287	
288	  priv->running = true;
289	  spin_unlock_irqrestore(&priv->lock, flags);
290	
291	  /* Enable the ADC clock and data path.  From here the FIFO fills at the
292	   * configured sample rate; the read callback drains it.
293	   */
294	
295	  bk7258_adc_start();
296	  return OK;
297	}
