300	static int bk7258_capture_stop(FAR struct audio_lowerhalf_s *dev)
301	{
302	  FAR struct bk7258_capture_s *priv = (FAR struct bk7258_capture_s *)dev;
303	  irqstate_t flags;
304	
305	  flags = spin_lock_irqsave(&priv->lock);
306	  if (priv->closing)
307	    {
308	      spin_unlock_irqrestore(&priv->lock, flags);
309	      return -ESHUTDOWN;
310	    }
311	
312	  priv->running = false;
313	  spin_unlock_irqrestore(&priv->lock, flags);
314	
315	  bk7258_adc_stop();
316	  return OK;
317	}
318	#endif
319	
320	static int bk7258_capture_shutdown(FAR struct audio_lowerhalf_s *dev)
321	{
322	  FAR struct bk7258_capture_s *priv = (FAR struct bk7258_capture_s *)dev;
323	  irqstate_t flags;
324	
325	  flags = spin_lock_irqsave(&priv->lock);
326	  priv->closing = true;
327	  priv->running = false;
328	  spin_unlock_irqrestore(&priv->lock, flags);
329	
330	  if (priv->configured)
331	    {
332	      /* Stops the capture clock, drops MIC enables and restores the digital
333	       * defaults (subsystem clock/power stays up).
334	       */
335	
336	      bk7258_adc_deinit();
337	    }
338	  else
339	    {
340	      bk7258_adc_stop();
341	    }
342	
343	  /* Lift the barrier so the registered lower half is reusable by a later
344	   * open.
345	   */
346	
347	  flags = spin_lock_irqsave(&priv->lock);
348	  priv->configured = false;
349	  priv->closing    = false;
350	  spin_unlock_irqrestore(&priv->lock, flags);
351	
352	  return OK;
353	}
354	
355	static int bk7258_capture_read(FAR struct audio_lowerhalf_s *dev,
356	                               FAR char *buffer, size_t buflen)
357	{
358	  FAR struct bk7258_capture_s *priv = (FAR struct bk7258_capture_s *)dev;
359	  FAR int16_t *dst = (FAR int16_t *)buffer;
360	  size_t nsamples = buflen / sizeof(int16_t);
361	  size_t i;
362	  irqstate_t flags;
363	
364	  if ((buflen & 1u) != 0u || nsamples == 0)
365	    {
366	      return -EINVAL;
367	    }
368	
369	  flags = spin_lock_irqsave(&priv->lock);
370	  if (!priv->running)
371	    {
372	      spin_unlock_irqrestore(&priv->lock, flags);
373	      return -EPIPE;
374	    }
375	
376	  spin_unlock_irqrestore(&priv->lock, flags);
377	
378	  for (i = 0; i < nsamples; i++)
379	    {
380	      uint32_t word;
381	
382	      if (bk7258_adc_fifo_empty())
383	        {
384	          break;
385	        }
386	
387	      word   = bk7258_adc_fifo_read();
388	      dst[i] = (int16_t)(word & UINT32_C(0xFFFF));
389	    }
390	
391	  if (i == 0)
392	    {
393	      return -EAGAIN;
394	    }
395	
396	  return (int)(i * sizeof(int16_t));
397	}
