21	extern const void *const _vectors[];
22	
23	const struct bk7258_ap_image_contract_s g_bk7258_ap_image_contract
24	  __attribute__((section(".ap_contract"), used)) =
25	{
26	  .magic = BK7258_AP_IMAGE_MAGIC,
27	  .abi_version = BK7258_AP_BOOT_ABI_VERSION,
28	  .build_id = BK7258_AP_BUILD_ID,
29	  .vector_base = BK7258_AP_XIP_VECTOR_BASE,
30	};
31	
32	void __start(void)
33	{
34	  const uint32_t *source;
35	  uint32_t *destination;
36	
37	  __asm__ volatile ("cpsid i" : : : "memory");
38	
39	  /* CPU1 may inherit cache state from the Bootloader/vendor AP lifecycle.
40	   * A2-1 has no cache-coherent Mailbox transport yet, so use a deterministic
41	   * uncached shared-SRAM path for SWAP and RPMSG_SHM. */
42	
43	  if ((getreg32(NVIC_CFGCON) & NVIC_CFGCON_DC) != 0)
44	    {
45	      up_disable_dcache();
46	    }
47	
48	  /* CPU1 has a private I-cache and starts from reset rather than inheriting
49	   * CPU0's Bootloader execution state. Match the vendor CPU1 startup contract
50	   * before executing the TIMER_ARCH and RPMsg paths from XIP. */
51	
52	  up_enable_icache();
53	
54	  putreg32((uintptr_t)_vectors, NVIC_VECTAB);
55	  __asm__ volatile ("dsb\n\tisb" : : : "memory");
56	
57	#ifdef CONFIG_BK7258_MAILBOX
58	  /* A warm reset keeps the SYS-level mailbox routes of the previous boot
59	   * alive while SRAM is cleared.  Disable both AP routes here so no stale
60	   * doorbell can pend or fire anywhere in the bring-up window;
61	   * bk7258_mbox_init() drains the stale FIFO entries and re-arms them. */
62	
63	  modifyreg32(BK7258_SYS_CPU1_INT_EN_HI, BK7258_SYS_MAILBOX_INT_EN, 0);
64	  modifyreg32(BK7258_SYS_CPU2_INT_EN_HI, BK7258_SYS_MAILBOX_INT_EN, 0);
65	#endif
66	
67	#ifdef CONFIG_SMP
68	  /* Pin CPU1's interrupt stack and select PSP for thread mode.  Without
69	   * this, CPU1's thread stack runs on the initial MSP and can grow down into
70	   * CPU2's stack region, corrupting the MSP-based core identification used by
71	   * up_cpu_index().  With the MSP fixed to CPU1's own interrupt stack, the
72	   * running (PSP) stacks never overlap CPU2's region. */
73	
74	  arm_initialize_stack();
75	#endif
76	
77	  for (destination = (uint32_t *)_sbss;
78	       destination < (uint32_t *)_ebss; )
79	    {
80	      *destination++ = 0;
81	    }
82	
83	  for (source = (const uint32_t *)_eronly,
84	       destination = (uint32_t *)_sdata;
85	       destination < (uint32_t *)_edata; )
86	    {
87	      *destination++ = *source++;
88	    }
89	
90	  bk7258_ap_record_mark_reset((uint32_t)(uintptr_t)_vectors,
91	                              (uint32_t)(uintptr_t)_vectors[1]);
92	  bk7258_ap_dbg_mark(BK7258_AP_DBG_MARK_RESET_DONE);
93	
94	  /* No notifier registration here: anything that takes sched_lock() before
95	   * nx_start()'s tasklist_initialize() dereferences a NULL TCB inside
96	   * _assert() and double-faults into a silent lockup. */
97	
98	  bk7258_ap_dbg_mark(BK7258_AP_DBG_MARK_BEFORE_NX);
99	  nx_start();
100	
101	  for (; ; )
102	    {
103	    }
104	}
