331	static int bk7258_rptun_register_callback(struct rptun_dev_s *dev,
332	                                          rptun_callback_t callback,
333	                                          void *arg)
334	{
335	  struct bk7258_rptun_dev_s *priv =
336	    container_of(dev, struct bk7258_rptun_dev_s, rptun);
337	  irqstate_t flags;
338	
339	  flags = enter_critical_section();
340	  priv->callback = callback;
341	  priv->callback_arg = arg;
342	  leave_critical_section(flags);
343	
344	  if (callback != NULL)
345	    {
346	      /* Match the established NuttX nRF53/STM32 RPTUN pattern: scan once
347	       * after callback registration to cover peer writes that predate local
348	       * IRQ setup.  All subsequent notifications are hardware-driven.
349	       */
350	
351	      callback(arg, RPTUN_NOTIFY_ALL);
352	    }
353	
354	  return 0;
355	}
356	
357	static void bk7258_rptun_mbox_callback(uint8_t src_cpu, uint32_t data0,
358	                                       uint32_t data1, void *arg)
359	{
360	  struct bk7258_rptun_dev_s *priv = arg;
361	  unsigned int local = priv->master ? 0 : 1;
362	  uint8_t peer = priv->master ? 1 : 0;
363	
364	  (void)data0;
365	  if (src_cpu != peer || data1 != BK7258_MBOX_RPTUN_MAGIC)
366	    {
367	      return;
368	    }
369	
370	  /* Re-arm the direction before scanning.  A concurrent sender either
371	   * coalesced before this clear (and is covered by this scan), or observes
372	   * zero and emits a new hardware doorbell.
373	   */
374	
375	  priv->shmem->mbox_pending[local] = 0;
376	  bk7258_rptun_barrier();
377	  if (priv->callback != NULL)
378	    {
379	      priv->callback(priv->callback_arg, RPTUN_NOTIFY_ALL);
380	    }
381	}
