383	int bk7258_rptun_initialize(void)
384	{
385	  unsigned int local = g_bk7258_rptun.master ? 0 : 1;
386	  int ret;
387	
388	  bk7258_rptun_enable_shared_sram();
389	
390	  if (g_bk7258_rptun.master)
391	    {
392	      memset(g_bk7258_rptun.shmem, 0, CONFIG_BK7258_RPMSG_SHM_SIZE);
393	      bk7258_rptun_barrier();
394	    }
395	
396	  ret = bk7258_mbox_attach(bk7258_rptun_mbox_callback,
397	                           &g_bk7258_rptun);
398	  if (ret < 0)
399	    {
400	      return ret;
401	    }
402	
403	  ret = bk7258_mbox_init(g_bk7258_rptun.master);
404	  if (ret < 0)
405	    {
406	      return ret;
407	    }
408	
409	  /* Mailbox init has discarded entries left by an earlier boot.  Re-arm the
410	   * matching shared latch only after that drain, so a restarted core cannot
411	   * leave its peer permanently coalescing against stale state.
412	   */
413	
414	  g_bk7258_rptun.shmem->mbox_pending[local] = 0;
415	  bk7258_rptun_barrier();
416	
417	  ret = rptun_initialize(&g_bk7258_rptun.rptun);
418	  if (ret < 0)
419	    {
420	      return ret;
421	    }
422	
